steps.script:
var p = PhaseManager.get_current_phase_instance()
for i in range(4):
	if p == null or not p.has_pending_stratagem_window():
		break
	var w = p.get_pending_stratagem_window()
	NetworkIntegration.route_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(w.get("player", 1)), "window_id": str(w.get("window_id", ""))})
return true

var main = tree.root.get_node("Main")
DebugLogger._flush_buffer()
var lf = FileAccess.open(DebugLogger.get_real_log_file_path(), FileAccess.READ)
var lines := 0
while lf != null and not lf.eof_reached():
	lf.get_line()
	lines += 1
main.set_meta("f3_log_mark", lines)
return lines > 0

var p = tree.root.get_node_or_null("Main/ReservesPanel")
var row = p.get_row(2, "U_KOMMANDOS_H")
if row == null:
	return "no Kommandos row"
var h = row.find_child("Hint", true, false)
return str(h.text) if h != null else "no Hint label"

# The panel lists richest first; scroll the Kommandos row into view for the capture.
var p = tree.root.get_node_or_null("Main/ReservesPanel")
var row = p.get_row(2, "U_KOMMANDOS_H")
var sc = row.get_parent()
while sc != null and not (sc is ScrollContainer):
	sc = sc.get_parent()
if sc == null:
	return false
sc.ensure_control_visible(row)
return true

var m = tree.root.get_node("Main")
var v = m._deep_strike_exclusion_visual
if v == null or not is_instance_valid(v) or v._last_label_pos == Vector2.INF:
	return "no label drawn"
var board = m.get_node("BoardRoot")
var p: Vector2 = board.to_local(v.to_global(v._last_label_pos))
m.view_zoom = 1.6
m.view_offset = p - Vector2(650.0, 380.0) / 1.6
m.update_view_transform()
SettingsService.set_placement_clamp_to_exclusion(false)
var cursor := Vector2(1300.0, 900.0)
Input.warp_mouse(cursor)
var motion := InputEventMouseMotion.new()
motion.position = cursor
motion.global_position = cursor
Input.parse_input_event(motion)
return "framed"

var dc = tree.current_scene.deployment_controller
if dc.is_placing():
	dc.reset_unit()
return dc.is_placing()

# The Kommandos (Infiltrators) back to undeployed, so the Deployment phase has
# a unit to place (as iss068_infiltrators_8in_11e does).
var u = GameState.state.units.U_KOMMANDOS_H
u["status"] = GameStateData.UnitStatus.UNDEPLOYED
u["reserve_type"] = null
if u.has("flags"):
	u.flags.erase("in_reserves")
for pm in u.models:
	pm.position = null
return int(u.status)

# Found by its text, not its node name, so the same check runs on code that
# predates the RulesBriefLabel name.
var b = tree.root.get_node_or_null("Main/PhaseTransitionBanner")
for l in b.find_children("*", "Label", true, false):
	if str(l.text).begins_with("Alternate placing units"):
		return str(l.text)
return "no Deployment rules brief on the banner"

# The runner's screenshot act hides the PhaseTransitionBanner (capture hygiene),
# so grab this frame directly while the banner is up.
var b = tree.root.get_node_or_null("Main/PhaseTransitionBanner")
if b == null or not b.visible:
	return "banner already gone"
var img = tree.root.get_viewport().get_texture().get_image()
DirAccess.make_dir_recursive_absolute(ProjectSettings.globalize_path("user://test_results/scenarios"))
var path = ProjectSettings.globalize_path("user://test_results/scenarios/rules_text_standoff_8in_11e_03_deployment_banner_infiltrators_8in.png")
print("[F3-SCENARIO] banner capture: ", path)
return "saved" if img.save_png(path) == OK else "save failed"

var m = tree.root.get_node("Main")
var ids := []
for i in range(m.unit_list.item_count):
	ids.append(str(m.unit_list.get_item_metadata(i)))
print("[F3-SCENARIO] deployment list: ", ids)
return ids.find("U_KOMMANDOS_H")

var m = tree.root.get_node("Main")
var v = m.deployment_controller.infiltrator_exclusion_visual
if v == null or not is_instance_valid(v) or v._last_label_pos == Vector2.INF:
	return "no label drawn"
var board = m.get_node("BoardRoot")
var p: Vector2 = board.to_local(v.to_global(v._last_label_pos))
m.view_zoom = 1.6
m.view_offset = p - Vector2(650.0, 380.0) / 1.6
m.update_view_transform()
SettingsService.set_placement_clamp_to_exclusion(false)
var cursor := Vector2(1300.0, 900.0)
Input.warp_mouse(cursor)
var motion := InputEventMouseMotion.new()
motion.position = cursor
motion.global_position = cursor
Input.parse_input_event(motion)
return "framed"

var sm = tree.root.get_node("Main")._settings_menu
for l in sm.find_children("*", "Label", true, false):
	if str(l.text).begins_with("On: aiming a Deep Strike"):
		return str(l.text).contains("inside the 8\" enemy exclusion zone") and not str(l.text).contains("9\"")
return "no placement-clamp help label"

# Bring the option into view for the capture.
var sm = tree.root.get_node("Main")._settings_menu
var cb = sm._placement_clamp_checkbox
var sc = cb.get_parent()
while sc != null and not (sc is ScrollContainer):
	sc = sc.get_parent()
if sc != null:
	sc.ensure_control_visible(cb)
return true

var main = tree.root.get_node("Main")
DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_real_log_file_path(), FileAccess.READ)
var mark := int(main.get_meta("f3_log_mark", 0))
var i := 0
var n := 0
while f != null and not f.eof_reached():
	var l := f.get_line()
	i += 1
	if i > mark and l.contains("[ERROR"):
		n += 1
		print("[F3-SCENARIO] debug-log ERROR: ", l)
return n
